package com.jprofilerx.ui;

import com.jprofilerx.config.AppSettings;
import com.jprofilerx.process.*;
import com.jprofilerx.monitoring.*;
import com.jprofilerx.memory.MemoryAnalysis;
import com.jprofilerx.snapshot.SnapshotService;
import com.jprofilerx.leak.LeakDetector;
import com.jprofilerx.report.ReportExporter;
import com.jprofilerx.jfr.JfrSupport;
import com.sun.management.HotSpotDiagnosticMXBean;
import javafx.application.Platform;
import javafx.collections.*;
import javafx.geometry.*;
import javafx.scene.Parent;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.*;
import javax.management.MBeanServerConnection;
import java.lang.management.ManagementFactory;
import java.nio.file.*;
import java.util.*;

public final class MainWindow extends BorderPane {
    private final Stage stage; private final AppSettings settings; private final JvmProcessDiscovery discovery;
    private final JmxConnectionService connections; private final MonitoringService monitoring;
    private final SnapshotService snapshots; private final LeakDetector detector; private final ReportExporter exporter;
    private final ComboBox<JvmProcessInfo> processBox = new ComboBox<>();
    private final Label connectionLabel = new Label("● Disconnected"), targetLabel = new Label("No target selected"), durationLabel = new Label("Monitoring idle");
    private final Label statusLabel = new Label("Ready — select a local JVM to begin");
    private final VBox content = new VBox(16); private final ListView<String> findingsList = new ListView<>();
    private MetricSnapshot latest; private long connectedAt; private String activePage = "Overview";
    private final Map<String, Button> navButtons = new LinkedHashMap<>();

    public MainWindow(Stage stage, AppSettings settings, JvmProcessDiscovery discovery, JmxConnectionService connections,
                      MonitoringService monitoring, SnapshotService snapshots, LeakDetector detector, ReportExporter exporter) {
        this.stage=stage; this.settings=settings; this.discovery=discovery; this.connections=connections; this.monitoring=monitoring; this.snapshots=snapshots; this.detector=detector; this.exporter=exporter;
        setLeft(buildSidebar()); setTop(buildToolbar()); setCenter(buildCenter()); setBottom(buildStatusBar());
        monitoring.setListener(s -> Platform.runLater(() -> onMetrics(s)));
        refreshProcesses(); showPage("Overview");
        if (settings.isAutoMonitor()) statusLabel.setText("Automatic monitoring is enabled; connect to a JVM to start.");
    }
    private Parent buildSidebar() {
        VBox side = new VBox(8); side.setPadding(new Insets(22,14,18,14)); side.setPrefWidth(225); side.getStyleClass().add("sidebar");
        Label brand = new Label("JProfilerX"); brand.getStyleClass().add("brand"); Label sub = new Label("JVM PERFORMANCE SUITE"); sub.getStyleClass().add("eyebrow");
        side.getChildren().addAll(brand,sub,new Separator());
        String[] pages={"Overview","Memory Analysis","Garbage Collection","Threads","Classes","Snapshots","Leak Detection","Reports","Settings"};
        for (String p:pages) { Button b=new Button(p); b.setMaxWidth(Double.MAX_VALUE); b.setAlignment(Pos.CENTER_LEFT); b.getStyleClass().add("nav-button"); b.setOnAction(e->showPage(p)); navButtons.put(p,b); side.getChildren().add(b); }
        Region spacer=new Region(); VBox.setVgrow(spacer,Priority.ALWAYS); side.getChildren().addAll(spacer,new Label("JDK 21  •  LOCAL ONLY"));
        return side;
    }
    private Parent buildToolbar() {
        HBox bar=new HBox(10); bar.setPadding(new Insets(14,22,14,22)); bar.setAlignment(Pos.CENTER_LEFT); bar.getStyleClass().add("toolbar");
        Label title=new Label("TARGET JVM"); title.getStyleClass().add("eyebrow"); processBox.setPromptText("Discover local Java processes…"); processBox.setPrefWidth(420);
        Button refresh=new Button("↻ Refresh"); refresh.setOnAction(e->refreshProcesses()); Button connect=new Button("Connect"); connect.getStyleClass().add("primary-button"); connect.setOnAction(e->connect());
        Button disconnect=new Button("Disconnect"); disconnect.setOnAction(e->disconnect());
        bar.getChildren().addAll(title,processBox,refresh,connect,disconnect); return bar;
    }
    private Parent buildCenter() { content.setPadding(new Insets(24)); content.getStyleClass().add("page-content"); ScrollPane scroll=new ScrollPane(content); scroll.setFitToWidth(true); scroll.getStyleClass().add("scroll-pane"); return scroll; }
    private Parent buildStatusBar() {
        HBox bar=new HBox(18,connectionLabel,new Separator(),targetLabel,new Separator(),durationLabel,new Region(),statusLabel); HBox.setHgrow(bar.getChildren().get(5),Priority.ALWAYS);
        bar.setPadding(new Insets(9,18,9,18)); bar.getStyleClass().add("statusbar"); return bar;
    }
    private void refreshProcesses() {
        try { String keep=processBox.getValue()==null?null:processBox.getValue().pid(); List<JvmProcessInfo> list=discovery.discover(); processBox.getItems().setAll(list); if(keep!=null) list.stream().filter(p->p.pid().equals(keep)).findFirst().ifPresent(processBox::setValue); statusLabel.setText(list.size()+" Java process(es) discovered"); }
        catch(Exception e){ alert("Process discovery failed",e.getMessage()); }
    }
    private void connect() {
        JvmProcessInfo p=processBox.getValue(); if(p==null){alert("Select a process","Choose a JVM process first.");return;}
        try { MBeanServerConnection c=connections.connect(p.pid()); monitoring.attach(c,p.pid()); monitoring.start(); connectedAt=System.currentTimeMillis();
            connectionLabel.setText("● Connected"); connectionLabel.getStyleClass().setAll("connected"); targetLabel.setText("PID "+p.pid()+" · "+p.displayName()); statusLabel.setText("Connected using local JMX attach");
        } catch(Exception e){ alert("Could not connect to PID "+p.pid(),e.getMessage()); statusLabel.setText("Connection failed — see details"); }
    }
    private void disconnect(){monitoring.stop();connections.disconnect();latest=null;connectionLabel.setText("● Disconnected");connectionLabel.getStyleClass().setAll("disconnected");targetLabel.setText("No target selected");durationLabel.setText("Monitoring idle");statusLabel.setText("Disconnected safely");showPage(activePage);}
    private void onMetrics(MetricSnapshot s){latest=s; durationLabel.setText("Monitoring "+formatDuration(System.currentTimeMillis()-connectedAt)); statusLabel.setText("Last sample "+s.timestamp()); if(activePage.equals("Overview")||activePage.equals("Memory Analysis")||activePage.equals("Garbage Collection")) showPage(activePage); updateFindings();}
    private void showPage(String page){activePage=page;navButtons.forEach((k,b)->b.getStyleClass().remove("selected"));if(navButtons.containsKey(page))navButtons.get(page).getStyleClass().add("selected");content.getChildren().clear();
        Label heading=new Label(page);heading.getStyleClass().add("page-title");content.getChildren().add(heading);
        switch(page){case "Overview"->overview();case "Memory Analysis"->memoryPage();case "Garbage Collection"->gcPage();case "Threads"->threadsPage();case "Classes"->classesPage();case "Snapshots"->snapshotsPage();case "Leak Detection"->leakPage();case "Reports"->reportsPage();case "Settings"->settingsPage();default->content.getChildren().add(new Label("Unknown page"));}
    }
    private void overview(){
        if(latest==null){emptyState("Connect to a running JVM to view live memory, GC, thread and class-loading metrics.");return;}
        GridPane cards=new GridPane();cards.setHgap(12);cards.setVgap(12);cards.add(metricCard("HEAP USED",MemoryAnalysis.formatBytes(latest.heapUsed()),String.format(Locale.ROOT,"%.1f%% of max",latest.heapPercent())),0,0);cards.add(metricCard("NON-HEAP USED",MemoryAnalysis.formatBytes(latest.nonHeapUsed()),"Committed "+MemoryAnalysis.formatBytes(latest.nonHeapCommitted())),1,0);cards.add(metricCard("LIVE THREADS",Integer.toString(latest.liveThreads()),"Peak "+latest.peakThreads()+" · Daemon "+latest.daemonThreads()),2,0);cards.add(metricCard("LOADED CLASSES",String.format("%,d",latest.loadedClasses()),String.format("%,d total loaded · %,d unloaded",latest.totalLoadedClasses(),latest.unloadedClasses())),3,0);cards.add(metricCard("GC COLLECTIONS",Long.toString(latest.gcCount()),latest.gcTimeMs()+" ms cumulative"),0,1);cards.add(metricCard("JVM UPTIME",formatDuration(latest.uptimeMs()),latest.runtimeName()),1,1);cards.add(metricCard("HEAP COMMITTED",MemoryAnalysis.formatBytes(latest.heapCommitted()),"Maximum "+MemoryAnalysis.formatBytes(latest.heapMax())),2,1);cards.add(metricCard("NON-HEAP COMMITTED",MemoryAnalysis.formatBytes(latest.nonHeapCommitted()),"Runtime management bean"),3,1);for(int i=0;i<4;i++)GridPane.setHgrow(cards.getChildren().get(i),Priority.ALWAYS);content.getChildren().add(cards);
        content.getChildren().add(chart("Heap & non-heap memory", "Memory (MiB)", memorySeries())); content.getChildren().add(chart("Live thread count", "Threads", threadSeries()));
        HBox actions=new HBox(10);Button pause=new Button(monitoring.isPaused()?"Resume monitoring":"Pause monitoring");pause.setOnAction(e->{if(monitoring.isPaused())monitoring.resume();else monitoring.pause();showPage("Overview");});Button reset=new Button("Reset chart history");reset.setOnAction(e->{monitoring.resetHistory();showPage("Overview");});Button export=new Button("Export current metrics");export.setOnAction(e->exportCurrent());Button heap=new Button("Generate heap dump…");heap.setOnAction(e->heapDump());actions.getChildren().addAll(pause,reset,export,heap);content.getChildren().add(actions);
    }
    private void memoryPage(){if(latest==null){emptyState("Connect to a JVM to inspect its memory pools.");return;}content.getChildren().add(metricCard("HEAP / NON-HEAP",MemoryAnalysis.formatBytes(latest.heapUsed())+" / "+MemoryAnalysis.formatBytes(latest.nonHeapUsed()),"Heap max "+MemoryAnalysis.formatBytes(latest.heapMax())));TableView<MemoryPoolMetric> table=new TableView<>();table.getColumns().add(col("Pool",MemoryPoolMetric::name));table.getColumns().add(col("Type",MemoryPoolMetric::type));table.getColumns().add(col("Used",p->MemoryAnalysis.formatBytes(p.used())));table.getColumns().add(col("Committed",p->MemoryAnalysis.formatBytes(p.committed())));table.getColumns().add(col("Maximum",p->MemoryAnalysis.formatBytes(p.max())));table.getColumns().add(col("Usage",p->p.utilizationPercent()<0?"N/A":String.format("%.1f%%",p.utilizationPercent())));table.getColumns().add(col("Threshold",p->p.thresholdSupported()?MemoryAnalysis.formatBytes(p.threshold()):"Unsupported"));table.setItems(FXCollections.observableArrayList(MemoryAnalysis.sortByUsage(latest.pools())));table.setPrefHeight(420);content.getChildren().addAll(section("Memory pools", "Pool names and limits are supplied by the target JVM; undefined maxima are shown as unavailable."),table,chart("Memory history","MiB",memorySeries()));}
    private void gcPage(){if(latest==null){emptyState("Connect to a JVM to monitor garbage collector counters.");return;}content.getChildren().addAll(metricCard("CUMULATIVE GC",latest.gcCount()+" collections",latest.gcTimeMs()+" ms reported collection time"),section("Collector counters","MXBean counters are cumulative snapshots. Counter deltas estimate activity between polls; they do not expose every individual GC event."));TableView<GcMetric> t=new TableView<>();t.getColumns().add(col("Collector",GcMetric::name));t.getColumns().add(col("Collection count",g->Long.toString(g.collectionCount())));t.getColumns().add(col("Collection time",g->g.collectionTimeMs()+" ms"));t.setItems(FXCollections.observableArrayList(latest.collectors()));t.setPrefHeight(250);content.getChildren().add(t);content.getChildren().add(chart("GC cumulative time","Milliseconds",gcSeries()));content.getChildren().add(new Label(JfrSupport.availabilityMessage()));}
    private void threadsPage(){if(latest==null){emptyState("Connect to a JVM to inspect threads.");return;}if(latest.deadlockedThreadIds().length>0)content.getChildren().add(warning("Deadlock detected",Arrays.toString(latest.deadlockedThreadIds())));TableView<ThreadMetric> t=new TableView<>();t.getColumns().add(col("ID",x->Long.toString(x.id())));t.getColumns().add(col("Name",ThreadMetric::name));t.getColumns().add(col("State",ThreadMetric::state));t.getColumns().add(col("Daemon",x->Boolean.toString(x.daemon())));t.getColumns().add(col("CPU time",x->x.cpuTimeNanos()<0?"Unavailable":String.format(Locale.ROOT,"%.2f ms",x.cpuTimeNanos()/1e6)));t.getColumns().add(col("Lock",ThreadMetric::lockName));t.setItems(FXCollections.observableArrayList(latest.threads()));t.setPrefHeight(560);content.getChildren().addAll(metricCard("THREADS",Integer.toString(latest.liveThreads()),"Peak "+latest.peakThreads()+" · Daemon "+latest.daemonThreads()),t);}
    private void classesPage(){if(latest==null){emptyState("Connect to a JVM to inspect class-loading metrics.");return;}content.getChildren().addAll(metricCard("CURRENTLY LOADED",String.format("%,d",latest.loadedClasses()),String.format("%,d loaded since start · %,d unloaded",latest.totalLoadedClasses(),latest.unloadedClasses())),section("Class histogram","A loaded-class count is not an object count or a memory measurement. A full class histogram is not collected by this build because it can trigger expensive target-side diagnostic work."));}
    private void snapshotsPage(){if(latest==null)emptyState("Connect to a JVM before capturing a metric snapshot.");else{Button save=new Button("Capture snapshot");save.getStyleClass().add("primary-button");save.setOnAction(e->{try{Path p=snapshots.save(latest,Path.of(settings.getSnapshotDirectory()));statusLabel.setText("Snapshot saved: "+p);alert("Snapshot saved",p.toString());}catch(Exception ex){alert("Snapshot failed",ex.getMessage());}});Button compare=new Button("Compare two saved snapshots…");compare.setOnAction(e->compareSnapshots());content.getChildren().addAll(section("Metric snapshots","Snapshots contain timestamped MXBean metrics and are saved locally as JSON."),new HBox(10,save,compare));}}
    private void leakPage(){content.getChildren().add(section("Heuristic anomaly detection","Findings require a minimum sample window. Heap growth alone is not proof of a memory leak. Compare post-GC baselines under a repeatable workload."));updateFindings();findingsList.setPrefHeight(500);content.getChildren().add(findingsList);}
    private void updateFindings(){if(findingsList==null)return;List<LeakDetector.Finding> f=detector.analyze(monitoring.history());List<String> lines=new ArrayList<>();for(var x:f)lines.add(x.severity()+" · "+x.title()+"\n"+x.explanation()+"\nEvidence: "+x.evidence()+"\nNext: "+x.recommendation());if(lines.isEmpty())lines.add("No findings. Collect more samples or investigate manually; absence of a warning does not prove the application is leak-free.");findingsList.getItems().setAll(lines);}
    private void compareSnapshots(){FileChooser fc=new FileChooser();fc.setTitle("Choose first snapshot");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("JSON snapshots","*.json"));var first=fc.showOpenDialog(stage);if(first==null)return;fc.setTitle("Choose second snapshot");var second=fc.showOpenDialog(stage);if(second==null)return;try{var a=snapshots.load(first.toPath());var b=snapshots.load(second.toPath());var d=snapshots.compare(a,b);alert("Snapshot comparison", "Heap delta: "+MemoryAnalysis.formatBytes(d.heapDelta())+"\nNon-heap delta: "+MemoryAnalysis.formatBytes(d.nonHeapDelta())+"\nLive thread delta: "+d.liveThreadDelta()+"\nLoaded class delta: "+d.loadedClassDelta()+"\nTotal classes loaded delta: "+d.totalLoadedClassDelta()+"\nUnloaded classes delta: "+d.unloadedClassDelta()+"\nGC count delta: "+d.gcCountDelta()+"\nGC time delta: "+d.gcTimeDeltaMs()+" ms");}catch(Exception ex){alert("Snapshot comparison failed",ex.getMessage());}}
    private void reportsPage(){content.getChildren().add(section("Export profiling data","Generate reports from actual collected samples. No target data is uploaded."));Button json=new Button("Export JSON report…"),csv=new Button("Export CSV time series…"),html=new Button("Export HTML report…");json.setOnAction(e->saveReport("json"));csv.setOnAction(e->saveReport("csv"));html.setOnAction(e->saveReport("html"));content.getChildren().addAll(json,csv,html);}
    private void saveReport(String type){List<MetricSnapshot> samples=monitoring.history();if(samples.isEmpty()){alert("No samples","Connect to a JVM and collect metrics first.");return;}FileChooser fc=new FileChooser();fc.setInitialDirectory(Path.of(settings.getReportDirectory()).toFile());fc.getExtensionFilters().add(new FileChooser.ExtensionFilter(type.toUpperCase()+" files","*."+type));fc.setInitialFileName("jprofilerx-report."+type);var file=fc.showSaveDialog(stage);if(file==null)return;try{Files.createDirectories(file.toPath().getParent());switch(type){case "json"->exporter.exportJson(samples,detector.analyze(samples),file.toPath());case "csv"->exporter.exportCsv(samples,file.toPath());case "html"->exporter.exportHtml(samples,detector.analyze(samples),file.toPath());}statusLabel.setText("Report exported: "+file);}catch(Exception ex){alert("Export failed",ex.getMessage());}}
    private void settingsPage(){content.getChildren().add(section("Monitoring preferences","Changes are saved locally in ~/.jprofilerx/settings.json."));Spinner<Integer> refresh=new Spinner<>(1,60,settings.getRefreshSeconds());Spinner<Integer> history=new Spinner<>(30,5000,settings.getHistoryLimit(),30);Spinner<Double> threshold=new Spinner<>(50d,99d,settings.getMemoryWarningPercent(),1d);Spinner<Integer> sensitivity=new Spinner<>(3,30,settings.getLeakSensitivity());Button save=new Button("Save settings");save.getStyleClass().add("primary-button");save.setOnAction(e->{settings.setRefreshSeconds(refresh.getValue());settings.setHistoryLimit(history.getValue());settings.setMemoryWarningPercent(threshold.getValue());settings.setLeakSensitivity(sensitivity.getValue());settings.save();monitoring.setRefreshSeconds(refresh.getValue());statusLabel.setText("Settings saved");});GridPane g=new GridPane();g.setHgap(16);g.setVgap(14);g.addRow(0,new Label("Refresh interval (seconds)"),refresh);g.addRow(1,new Label("Maximum history samples"),history);g.addRow(2,new Label("Memory warning threshold (%)"),threshold);g.addRow(3,new Label("Leak detection sample sensitivity"),sensitivity);g.add(save,1,4);content.getChildren().add(g);}
    private void heapDump(){if(latest==null||!connections.isConnected()){alert("No target","Connect to a JVM first.");return;}Alert confirm=new Alert(Alert.AlertType.WARNING,"Heap dumps may be very large and can contain passwords, tokens, personal data, and other sensitive application contents. Save locally and protect the file. Continue?",ButtonType.CANCEL,ButtonType.OK);confirm.setHeaderText("Generate a heap dump?");if(confirm.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.OK)return;FileChooser fc=new FileChooser();fc.setInitialFileName("heap-"+latest.pid()+".hprof");var file=fc.showSaveDialog(stage);if(file==null)return;statusLabel.setText("Heap dump in progress — target may pause while the dump is written");Thread worker=new Thread(()->{try{HotSpotDiagnosticMXBean bean=ManagementFactory.newPlatformMXBeanProxy(connections.serverConnection(),"com.sun.management:type=HotSpotDiagnostic",HotSpotDiagnosticMXBean.class);bean.dumpHeap(file.getAbsolutePath(),true);Platform.runLater(()->{statusLabel.setText("Heap dump created: "+file);alert("Heap dump created",file.toString());});}catch(Exception ex){Platform.runLater(()->alert("Heap dump unavailable",ex.getMessage()+"\nThe target may not be HotSpot-compatible or may not expose HotSpotDiagnosticMXBean."));}},"jprofilerx-heapdump");worker.setDaemon(true);worker.start();}

    private void exportCurrent(){if(latest==null){alert("No metrics","Connect to a JVM first.");return;}FileChooser fc=new FileChooser();fc.setInitialFileName("jprofilerx-current.json");var f=fc.showSaveDialog(stage);if(f==null)return;try{new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().writerWithDefaultPrettyPrinter().writeValue(f,latest);statusLabel.setText("Current metrics exported");}catch(Exception e){alert("Export failed",e.getMessage());}}
    private HBox metricCard(String label,String value,String detail){VBox b=new VBox(8);b.getStyleClass().add("metric-card");Label l=new Label(label);l.getStyleClass().add("eyebrow");Label v=new Label(value);v.getStyleClass().add("metric-value");Label d=new Label(detail);d.getStyleClass().add("muted");b.getChildren().addAll(l,v,d);HBox h=new HBox(b);h.setMaxWidth(Double.MAX_VALUE);HBox.setHgrow(b,Priority.ALWAYS);b.setMaxWidth(Double.MAX_VALUE);return h;}
    private VBox section(String title,String desc){VBox b=new VBox(5);Label t=new Label(title);t.getStyleClass().add("section-title");Label d=new Label(desc);d.getStyleClass().add("muted");d.setWrapText(true);b.getChildren().addAll(t,d);return b;}
    private void emptyState(String message){VBox box=new VBox(10);box.getStyleClass().add("empty-state");Label icon=new Label("◈");icon.getStyleClass().add("empty-icon");Label t=new Label("No JVM connected");t.getStyleClass().add("section-title");Label d=new Label(message);d.setWrapText(true);box.getChildren().addAll(icon,t,d);content.getChildren().add(box);}
    private Label warning(String title,String body){Label l=new Label("⚠ "+title+" — "+body);l.getStyleClass().add("warning");l.setWrapText(true);return l;}
    private LineChart<Number,Number> chart(String title,String yLabel,List<XYChart.Series<Number,Number>> data){NumberAxis x=new NumberAxis();x.setLabel("Sample");NumberAxis y=new NumberAxis();y.setLabel(yLabel);LineChart<Number,Number> c=new LineChart<>(x,y);c.setTitle(title);c.setAnimated(false);c.setCreateSymbols(false);c.setLegendVisible(true);c.setPrefHeight(300);c.getData().setAll(data);return c;}
    private List<XYChart.Series<Number,Number>> memorySeries(){List<XYChart.Series<Number,Number>> out=new ArrayList<>();XYChart.Series<Number,Number> heap=new XYChart.Series<>(),non=new XYChart.Series<>();heap.setName("Heap");non.setName("Non-heap");int i=0;for(MetricSnapshot s:monitoring.history()){heap.getData().add(new XYChart.Data<>(i,s.heapUsed()/1048576d));non.getData().add(new XYChart.Data<>(i++,s.nonHeapUsed()/1048576d));}out.add(heap);out.add(non);return out;}
    private List<XYChart.Series<Number,Number>> threadSeries(){XYChart.Series<Number,Number> s=new XYChart.Series<>();s.setName("Live threads");int i=0;for(MetricSnapshot m:monitoring.history())s.getData().add(new XYChart.Data<>(i++,m.liveThreads()));return List.of(s);}
    private List<XYChart.Series<Number,Number>> gcSeries(){XYChart.Series<Number,Number> s=new XYChart.Series<>();s.setName("Cumulative GC time");int i=0;for(MetricSnapshot m:monitoring.history())s.getData().add(new XYChart.Data<>(i++,m.gcTimeMs()));return List.of(s);}
    private <T> TableColumn<T,String> col(String title,java.util.function.Function<T,String> value){TableColumn<T,String> c=new TableColumn<>(title);c.setCellValueFactory(d->new javafx.beans.property.SimpleStringProperty(value.apply(d.getValue())));c.setPrefWidth(150);return c;}
    private void alert(String title,String message){Alert a=new Alert(Alert.AlertType.INFORMATION);a.setTitle("JProfilerX");a.setHeaderText(title);a.setContentText(message==null?"Unknown error":message);a.showAndWait();}
    private static String formatDuration(long ms){long s=ms/1000;return String.format(Locale.ROOT,"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);}
}
